//! 🪡️ A resident typed array transfer keeps its original source until every destination element is initialized.
use crate::{RetainedAllocationEffect,RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{OriginalEffectReply,OriginalEffectReplyComplete,OriginalWorkBindingIdentity,RetainedCloneProgress,RetainedCloneStep,RetainedCopy,retained_clone_grant_admits}};
use std::{mem::{size_of,ManuallyDrop,MaybeUninit},ptr::NonNull};

/// 🧺️ Owns one actual source array while its parent retains a stable uninitialized destination.
pub struct NativeArrayFieldPlacement<T,const N:usize>{source:ManuallyDrop<Option<Box<[T;N]>>>,target:NonNull<MaybeUninit<[T;N]>>,initialized:usize,work:OriginalWorkBindingIdentity,cancelled:bool,copy:RetainedCopy<T>}
unsafe impl<T:Send,const N:usize> Send for NativeArrayFieldPlacement<T,N>{}
impl<T,const N:usize> NativeArrayFieldPlacement<T,N>{
 /// 📏️ Quotes the resident source and placement headers.
 pub fn admission_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<[T;N]>>>()+size_of::<Option<Self>>(),depth:1,..Default::default()}}
 /// 🧭️ Transfers the original source into the resident typed placement owner.
 /// # Safety
 /// The destination must not overlap the source and must remain at the same address, uninitialized and exclusively owned by its parent until this placement is finished. The parent must not read or transfer it while the placement exists, and must keep it uninitialized on cancellation.
 pub unsafe fn admit_into<'r>(source:&mut Option<Box<[T;N]>>,target:&mut MaybeUninit<[T;N]>,output:&mut Option<Self>,copy:RetainedCopy<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{if source.is_none()||output.is_some(){return Err(ValueError::invariant("array placement admission slots changed"))}if effect.work_source_turn().is_none(){return Err(ValueError::invariant("array placement requires original Source"))}let demand=Self::admission_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array placement admission exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}*output=Some(Self{source:ManuallyDrop::new(source.take()),target:NonNull::from(target),initialized:0,work:OriginalWorkBindingIdentity::from_effect(effect),cancelled:false,copy});Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 fn authenticate(&self,effect:&RetainedAllocationEffect<'_>)->Result<(),ValueError>{if !self.work.matches_effect(effect){return Err(ValueError::invariant("array placement changed original Work"))}Ok(())}
 /// 🔢️ Returns the actual initialized prefix.
 pub fn initialized(&self)->usize{self.initialized}
 /// 📦️ Reports whether the original source is still resident.
 pub fn source_present(&self)->bool{self.source.is_some()}
 /// 🪪️ Reports the retained source allocation without transferring it.
 pub fn source_address(&self)->Option<*const T>{self.source.as_ref().map(|source|source.as_ptr())}
 /// 📏️ Quotes one bounded typed prefix and its native index.
 pub fn copy_demand(count:usize)->Result<RetirementDemand,ValueError>{let bytes=count.checked_mul(size_of::<T>()).and_then(|n|n.checked_add(size_of::<usize>())).ok_or_else(||ValueError::invariant("array placement copy extent overflow"))?;Ok(RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()})}
 /// ⛽️ Quotes each actual typed item and index update.
 pub fn copy_work(count:usize)->Result<u64,ValueError>{u64::try_from(size_of::<T>()).ok().and_then(|n|n.checked_add(2)).and_then(|n|u64::try_from(count).ok().and_then(|count|n.checked_mul(count))).and_then(|n|n.checked_add(1)).ok_or_else(||ValueError::invariant("array placement Work overflow"))}
 /// 📥️ Copies only the next admitted typed elements into the retained destination.
 pub fn copy_into<'r>(&mut self,count:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;let end=self.initialized.checked_add(count).filter(|end|*end<=N).ok_or_else(||ValueError::invariant("array placement prefix exceeds destination"))?;if self.cancelled||self.source.is_none(){return Err(ValueError::invariant("array placement source absent"))}if count==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}let demand=Self::copy_demand(count)?;let work=Self::copy_work(count)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array placement copy exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}let source=self.source.as_ref().ok_or_else(||ValueError::invariant("array placement source absent"))?;let _=&self.copy;unsafe{std::ptr::copy_nonoverlapping(source.as_ptr().add(self.initialized),self.target.as_ptr().cast::<T>().add(self.initialized),count)}self.initialized=end;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
 /// 📏️ Quotes release of the actual source allocation.
 pub fn release_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Box<[T;N]>>>()+size_of::<bool>(),release_bytes:size_of::<[T;N]>(),depth:1,..Default::default()}}
 fn release<'r>(&mut self,cancel:bool,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;if self.source.is_none()||(!cancel&&self.initialized!=N){return Err(ValueError::invariant("array placement source is not releasable"))}let demand=self.release_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array placement release exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}self.cancelled=cancel;drop(self.source.take());Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))))}
 /// 📤️ Releases the source after the destination is fully initialized.
 pub fn release_source_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.release(false,effect,reply)}
 /// 🛑️ Cancels without publishing a partially initialized destination.
 pub fn cancel_source_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.release(true,effect,reply)}
 /// 📏️ Quotes the resident terminal owner header.
 pub fn finish_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Self>>(),depth:1,..Default::default()}}
 /// 🏁️ Clears only an already settled resident owner.
 pub fn finish_into<'r>(owner:&mut Option<Self>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{let state=owner.as_ref().ok_or_else(||ValueError::invariant("array placement owner absent"))?;state.authenticate(effect)?;if state.source.is_some()||(!state.cancelled&&state.initialized!=N){return Err(ValueError::invariant("array placement remains active"))}let demand=Self::finish_demand();if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"array placement finish exceeded original Work")))),Err(error)=>return Ok(reply.complete(Err(error)))}drop(owner.take());Ok(reply.complete(Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))))}
}
impl<T,const N:usize> Drop for NativeArrayFieldPlacement<T,N>{fn drop(&mut self){if !std::thread::panicking(){assert!(self.source.is_none()&&(self.cancelled||self.initialized==N),"array field placement retains source or unfinished destination")}}}
